/**
 * The TOC public key derivation must equal the Go side (private/renet/pkg/chunkstore/toccrypt) byte for byte.
 * The vectors file is the oracle: generated by the Go test, copied here unchanged.
 */

import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { deriveTocPublicKeyLine } from '../toc-key.js';

interface Vector {
  name: string;
  kind: string;
  passphrase: string;
  passphraseHex: string;
  lineage: string;
  scalarHex: string;
  publicKeyHex: string;
  publicKeyLine: string;
}

const here = new URL('./toc_key_vectors.json', import.meta.url);
const upstream = new URL(
  '../../../../../private/renet/pkg/chunkstore/toccrypt/testdata/toc_key_vectors.json',
  import.meta.url
);
const file = JSON.parse(readFileSync(fileURLToPath(here), 'utf-8')) as {
  hash: string;
  info: string;
  vectors: Vector[];
};

describe('deriveTocPublicKeyLine', () => {
  it('uses the parameters the vectors were generated with', () => {
    expect(file.hash).toBe('sha256');
    expect(file.info).toBe('rediacc-backup-toc-v1');
    expect(file.vectors.length).toBeGreaterThan(0);
  });

  for (const v of file.vectors) {
    it(`matches the Go vector ${v.name}`, () => {
      expect(Buffer.from(v.passphrase, 'utf-8').toString('hex')).toBe(v.passphraseHex);
      expect(deriveTocPublicKeyLine(v.passphrase, v.lineage)).toBe(v.publicKeyLine);
    });
  }

  it('does not normalise: composed and decomposed forms derive different keys', () => {
    const lineage = 'lineage-x';
    const a = deriveTocPublicKeyLine('café', lineage);
    const b = deriveTocPublicKeyLine('café', lineage);
    expect(a).not.toBe(b);
  });

  it('returns exactly one public line and nothing private', () => {
    const line = deriveTocPublicKeyLine('x'.repeat(32), 'lin');
    expect(line).toMatch(/^rediacc-toc-x25519 [A-Za-z0-9+/]{43}=\n$/);
  });

  it('the committed vectors copy equals the renet file', (ctx) => {
    const upstreamPath = fileURLToPath(upstream);
    // A checkout without the private submodule has no oracle to compare against.
    if (!existsSync(upstreamPath)) ctx.skip();
    expect(readFileSync(fileURLToPath(here)).equals(readFileSync(upstreamPath))).toBe(true);
  });
});
